function icon(name: string, cls = "") {
  const s = document.createElementNS("http://www.w3.org/2000/svg", "svg");
  s.setAttribute("viewBox", name === "github" ? "0 0 16 16" : "0 0 24 24");
  s.setAttribute("aria-hidden", "true");
  s.setAttribute("class", `icon ${name === "github" ? "icon-fill" : ""} ${cls}`);
  s.innerHTML = ICONS[name];
  return s;
}
const mark = () => h("span", { className: "mark" }, icon("bubble"));
const logo = (href?: string) => {
  const kids = [mark(), h("span", { className: "wordmark", textContent: "asku" })];
  return href ? h("a", { className: "logo", href, ariaLabel: "asku home" }, ...kids) : h("span", { className: "logo" }, ...kids);
};

DOMPurify.addHook("afterSanitizeAttributes", (node) => {
  if (node.tagName === "A") { node.setAttribute("target", "_blank"); node.setAttribute("rel", "noopener noreferrer"); }
});
function md(src: string, extra = "") {
  const div = h("div", { className: `md ${extra}` });
  div.innerHTML = DOMPurify.sanitize(marked.parse(src, { async: false }) as string);
  return div;
}

// ---- app pages: a slim top bar and one centred column, built for phones
function shell(kids: Kid[], tag: "main" | "div" = "main") {
  return h("div", { className: "shell" },
    // no home link on an answer page: one stray tap would lose a half-filled form
    h("header", { className: "topbar" }, logo(location.pathname.startsWith("/a/") ? undefined : "/"), h("span", { className: "e2e" }, icon("lock"), "End-to-end encrypted")),
    h(tag, { className: "shell-main" }, ...kids));
}

type Kind = "wait" | "done" | "error" | "agent";
function stateEl(kind: Kind, title: string, detail?: string, ...extra: Kid[]) {
  const ico = kind === "wait" ? h("span", { className: "spinner" }) : icon(kind === "done" ? "check" : kind === "error" ? "alert" : "terminal");
  return h("section", { className: `state ${kind}`, role: kind === "error" ? "alert" : "status" },
    h("div", { className: "state-icon" }, ico),
    h("h1", { textContent: title }),
    detail ? p(detail, "state-detail") : null,
    ...extra);
}
// After swapping screens, move focus to the new heading so keyboard and screen-reader users land on it.
const show = (...kids: Kid[]) => {
  app.replaceChildren(shell(kids));
  const h1 = app.querySelector<HTMLElement>("h1");
  if (h1) { h1.tabIndex = -1; h1.focus({ preventScroll: true }); }
};
const status = (kind: Kind, title: string, detail?: string, ...extra: Kid[]) => show(stateEl(kind, title, detail, ...extra));
const live = (text: string) => h("p", { className: "live" }, h("span", { className: "pulse" }), text);
const home = () => h("a", { className: "btn btn-secondary", href: "/" }, `Go to ${location.host}`);
const startNew = (kind = "btn-secondary") => h("a", { className: `btn ${kind}`, href: "/start" }, "Start a new session");

// ---- persistence: the fragment is gone after first load, so key pair B and the write key live in IndexedDB.
// ponytail: IndexedDB unavailable (some private modes) means a reload loses the session; fine, the agent can start a new one.
const idb = new Promise<IDBDatabase>((resolve, reject) => {
  const r = indexedDB.open("asku", 1);
  r.onupgradeneeded = () => r.result.createObjectStore("s");
  r.onsuccess = () => resolve(r.result);
  r.onerror = () => reject(r.error);
});
async function db<T>(mode: IDBTransactionMode, fn: (s: IDBObjectStore) => IDBRequest<T>) {
  const d = await idb;
  return new Promise<T>((resolve, reject) => {
    const r = fn(d.transaction("s", mode).objectStore("s"));
    r.onsuccess = () => resolve(r.result);
    r.onerror = () => reject(r.error);
  });
}
const load = (sid: string) => db<State | undefined>("readonly", (s) => s.get(sid)).catch(() => undefined);
const save = (sid: string, st: State) => db("readwrite", (s) => s.put(st, sid)).catch(() => {});
const drop = (sid: string) => db("readwrite", (s) => s.delete(sid)).catch(() => {});

const post = (path: string, body: unknown, key?: string) =>
  fetch(path, {
    method: "POST",
    headers: { "content-type": "application/json", ...(key ? { authorization: `Bearer ${key}` } : {}) },
    body: JSON.stringify(body),
  });

// ---- controls
const opt = (o: Option) => (typeof o === "string" ? { value: o, label: o, md: undefined } : { value: o.value, label: o.label ?? o.value, md: o.md });

function choice(type: "radio" | "checkbox", name: string, value: string, label: string, checked: boolean, detail?: string) {
  const input = h("input", { type, name, value, checked, className: "pick" });
  return { input, el: h("label", { className: "opt" }, input, h("span", { className: "opt-body" }, h("span", { className: "opt-label", textContent: label }), detail ? md(detail) : null)) };
}

function yesNo(name: string, value: string, label: string, checked: boolean) {
  const input = h("input", { type: "radio", name, value, checked, className: "sr-only" });
  return { input, el: h("label", { className: `yn yn-${value}` }, input, icon(value === "yes" ? "check" : "x"), h("span", { textContent: label })) };
}

const range = (it: Item) => [
  it.min !== undefined && it.max !== undefined ? `${it.min} to ${it.max}` : it.min !== undefined ? `at least ${it.min}` : it.max !== undefined ? `at most ${it.max}` : "",
  it.step !== undefined ? `step ${it.step}` : "",
].filter(Boolean).join(" · ");

function field(it: Item, i: number) {
  const msg = h("p", { className: "q-err", id: `q-err-${it.id}` });
  const box = h("fieldset", { className: `q q-${it.type}` },
    h("legend", {},
      h("span", { className: "q-num", textContent: String(i + 1), ariaHidden: "true" }),
      h("span", { className: "q-label", textContent: it.label }),
      it.required ? h("span", { className: "req", textContent: "Required" }) : null),
    it.md ? md(it.md, "q-md") : null);
  const name = `f-${it.id}`;
  let value: () => unknown;
  let check = (): string | null => null;

  switch (it.type) {
    case "confirm": {
      const yes = yesNo(name, "yes", "Yes", it.default === true);
      const no = yesNo(name, "no", "No", it.default === false);
      box.append(h("div", { className: "seg" }, yes.el, no.el));
      value = () => (yes.input.checked ? true : no.input.checked ? false : undefined);
      break;
    }
    case "single":
    case "multi": {
      const multi = it.type === "multi";
      const def = new Set<string>(multi ? it.default ?? [] : it.default !== undefined ? [it.default] : []);
      const cs = it.options!.map(opt).map((o) => choice(multi ? "checkbox" : "radio", name, o.value, o.label, def.has(o.value), o.md));
      const hint = multi ? [it.min !== undefined && it.min > 1 && `pick at least ${it.min}`, it.max !== undefined && `at most ${it.max}`].filter(Boolean).join(", ") : "";
      box.append(h("div", { className: "opts" }, ...cs.map((c) => c.el)));
      if (hint) box.append(h("p", { className: "hint", textContent: hint[0].toUpperCase() + hint.slice(1) }));
      const picked = () => cs.filter((c) => c.input.checked).map((c) => c.input.value);
      value = () => (multi ? (picked().length ? picked() : undefined) : picked()[0]);
      if (multi) check = () => {
        const n = picked().length;
        if (n && it.min !== undefined && n < it.min) return `pick at least ${it.min}`;
        if (it.max !== undefined && n > it.max) return `pick at most ${it.max}`;
        return null;
      };
      break;
    }
    case "text": {
      const el = it.multiline ? h("textarea", { rows: 4 }) : h("input", { type: "text" });
      Object.assign(el, { placeholder: it.placeholder ?? "", value: it.default ?? "", className: "input", ariaLabel: it.label });
      if (it.maxLength) el.maxLength = it.maxLength;
      box.append(el);
      value = () => (el.value.trim() ? el.value : undefined);
      break;
    }
    case "number": {
      // iOS's decimal keypad has no minus key
      const el = h("input", { type: "number", inputMode: it.min !== undefined && it.min >= 0 ? "decimal" : "text", className: "input", ariaLabel: it.label, value: it.default !== undefined ? String(it.default) : "" });
      if (it.min !== undefined) el.min = String(it.min);
      if (it.max !== undefined) el.max = String(it.max);
      el.step = it.step !== undefined ? String(it.step) : "any";
      const bump = (d: number) => {
        const v = (el.value === "" ? it.default ?? it.min ?? 0 : el.valueAsNumber) + d * (it.step ?? 1);
        el.value = String(Math.round(Math.min(it.max ?? Infinity, Math.max(it.min ?? -Infinity, v)) * 1e9) / 1e9);
        el.dispatchEvent(new Event("input", { bubbles: true }));
      };
      const btn = (d: number) => h("button", { type: "button", className: `stepbtn ${d > 0 ? "step-up" : "step-down"}`, ariaLabel: d > 0 ? "Increase" : "Decrease", onclick: () => bump(d) }, icon(d > 0 ? "plus" : "minus"));
      const r = range(it);
      box.append(h("div", { className: "stepper" }, btn(-1), el, btn(1)));
      if (r) box.append(h("p", { className: "hint", textContent: r[0].toUpperCase() + r.slice(1) }));
      value = () => (el.value === "" ? undefined : el.valueAsNumber);
      check = () => (el.validity.valid ? null : el.validationMessage || "not a valid number");
      break;
    }
  }

  // a radio can't be unticked: optional ones get a way back to "skipped"
  if (!it.required && (it.type === "confirm" || it.type === "single")) {
    box.append(h("button", { type: "button", className: "clear", textContent: "Clear answer", onclick: () => {
      box.querySelectorAll<HTMLInputElement>("input:checked").forEach((x) => (x.checked = false));
      box.dispatchEvent(new Event("change", { bubbles: true }));
    } }));
  }
  box.querySelectorAll("input, textarea").forEach((x) => x.setAttribute("aria-describedby", msg.id));
  const comment = h("textarea", { rows: 2, className: "input", placeholder: "Comment for the agent", ariaLabel: `Comment on “${it.label}”` });
  const sumText = h("span", { textContent: "Add a comment" });
  const det = h("details", { className: "comment" }, h("summary", {}, icon("message"), sumText), comment);
  det.ontoggle = () => { if (det.open) comment.focus(); };
  comment.oninput = () => { sumText.textContent = comment.value.trim() ? "Comment added" : "Add a comment"; det.classList.toggle("has", !!comment.value.trim()); };
  box.append(msg, det);
  return { it, el: box, value: value!, check, comment, msg };
}

// The answer form, shared by the real page and the landing demos.
function buildForm(q: Question) {
  const fields: ReturnType<typeof field>[] = [];
  const note = h("textarea", { rows: 3, className: "input", placeholder: "Anything else the agent should know?" });
  const err = h("div", { className: "form-err", role: "alert" });
  const label = h("span", { textContent: "Send answers" });
  const btn = h("button", { type: "submit", className: "btn btn-primary btn-send" }, icon("lock"), label);
  const progress = h("span", { className: "progress" });
  const tail = h("label", { className: "q note" }, h("span", { className: "note-label" }, "Note for the agent", h("span", { className: "opt-tag", textContent: "Optional" })), note);
  const form = h("form", { className: "qform", noValidate: true },
    q.title || q.md ? h("header", { className: "qform-head" }, q.title ? h("h1", { textContent: q.title }) : null, q.md ? md(q.md, "context") : null) : null,
    tail,
    err,
    h("div", { className: "submit-bar" }, progress, btn));

  // Adds a batch's questions above the note, numbered on from the last; later batches get their title/md as a section head.
  const append = (b: Question, head = true) => {
    const fs = b.questions.map((it, i) => field(it, fields.length + i));
    fields.push(...fs);
    const sec = head && (b.title || b.md) ? h("header", { className: "qform-sec" }, b.title ? h("h2", { textContent: b.title }) : null, b.md ? md(b.md, "context") : null) : null;
    const els = [sec, ...fs.map((f) => f.el)].filter((e) => e !== null);
    tail.before(...els);
    refresh();
    return { els, fields: fs };
  };
  const remove = (fs: typeof fields) => {
    for (const x of fs) { fields.splice(fields.indexOf(x), 1); x.el.remove(); }
    refresh();
  };

  let tried = false;
  // mark: flag problems on the fields (after the first submit, flags then follow every edit); only: just these fields
  const collect = (mark = true, only = fields) => {
    tried ||= mark;
    const a: Answer = { answers: {}, skipped: [], comments: {}, note: note.value.trim() };
    const problems: string[] = [];
    for (const f of only) {
      const v = f.value();
      const bad = v === undefined ? (f.it.required ? "required" : null) : f.check();
      f.el.classList.toggle("invalid", tried && !!bad);
      f.el.querySelectorAll("[aria-describedby]").forEach((x) => x.setAttribute("aria-invalid", String(tried && !!bad)));
      f.msg.textContent = tried && bad ? bad[0].toUpperCase() + bad.slice(1) : "";
      if (bad) problems.push(`${f.it.label}: ${bad}`);
      else if (v === undefined) a.skipped.push(f.it.id);
      else a.answers[f.it.id] = v;
      if (f.comment.value.trim()) a.comments[f.it.id] = f.comment.value.trim();
    }
    if (tried) err.textContent = problems.length ? `Check ${problems.length === 1 ? "1 answer" : `${problems.length} answers`}: ${problems.join(" · ")}` : "";
    return { a, problems };
  };
  const refresh = () => {
    const n = fields.filter((f) => f.value() !== undefined).length;
    progress.textContent = `${n} of ${fields.length} answered`;
    if (tried) collect(false);
  };
  form.addEventListener("input", refresh);
  form.addEventListener("change", refresh);
  append(q, false);
  return { form, fields, note, tail, err, btn, label, collect, append, remove };
}

// ---- session
// One answer can cover several batches: it goes under the newest, and says which in its `seqs`.
async function send(sid: string, keys: Keys, st: State, seqs: number[], a: Answer | { note: string }) {
  const res = await post(`/s/${sid}/a`, await seal(keys, sid, "a", Math.max(...seqs), JSON.stringify(a)), st.key);
  // duplicate: a retry of an answer the relay already has
  if (res.status !== 204 && !(res.status === 409 && (await res.json().catch(() => ({}))).error === "duplicate")) throw new Error(`relay said ${res.status}`);
  st.answered.push(...seqs);
  await save(sid, st);
}

const sentState = () => stateEl("done", "Answers sent", "Encrypted on this device and delivered to your agent. Keep this tab open for follow-up questions.", live("Waiting for the agent's next question…"));
const smooth = (): ScrollBehavior => (matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth");

type Batch = [seq: number, q: Question];
type Fields = ReturnType<typeof buildForm>["fields"];
type Part = { seq: number; fields: Fields; foot: HTMLElement };
type Open = { f: ReturnType<typeof buildForm>; sending: boolean; add: (b: Batch) => void };

// Shows a form for one or more batches. Later batches go under it, with a chip pointing at them; with more than one
// open, each batch can be sent on its own, and the main button sends the rest.
function render(sid: string, keys: Keys, st: State, batches: Batch[], done: () => void): Open {
  const [[seq, q], ...rest] = batches;
  const f = buildForm(q);
  const born = Date.now();
  const parts: Part[] = [];
  let unseen = 0, first: Element | undefined;
  const said = h("p", { className: "sr-only", ariaLive: "polite" });
  const chip = h("button", { type: "button", className: "new-chip", onclick: () => first?.scrollIntoView({ behavior: smooth(), block: "start" }) });
  const seen = new IntersectionObserver((es) => {
    if (!es.some((x) => x.isIntersecting)) return;
    chip.remove(); unseen = 0; first = undefined; seen.disconnect();
  });
  const decline = h("button", { type: "button", className: "btn btn-secondary btn-sm" }, "Decline, send only the note");
  decline.onclick = () => submit(parts, true);
  f.tail.after(h("div", { className: "decline" }, decline));
  f.form.append(said);

  const part = (s: number, fs: Fields) => {
    const btn = h("button", { type: "button", className: "btn btn-secondary btn-sm" }, `Send ${fs.length === 1 ? "this answer" : `these ${fs.length} answers`}`);
    const p: Part = { seq: s, fields: fs, foot: h("div", { className: "batch-foot" }, btn) };
    btn.onclick = () => submit([p]);
    fs[fs.length - 1].el.after(p.foot);
    parts.push(p);
    f.form.classList.toggle("multi", parts.length > 1);
  };

  const busy = (on: boolean) => {
    o.sending = on;
    f.form.querySelectorAll<HTMLButtonElement>(".btn").forEach((b) => (b.disabled = on));
    f.label.textContent = on ? "Sending…" : "Send answers";
  };
  const submit = async (ps: Part[], declined = false) => {
    if (o.sending) return;
    const all = ps.length === parts.length;
    const fields = ps.flatMap((p) => p.fields);
    let a: Answer;
    if (declined) {
      if (!f.note.value.trim()) {
        f.err.textContent = "Write a note first, so the agent knows why you're not answering.";
        return f.note.focus();
      }
      a = { answers: {}, skipped: fields.map((x) => x.it.id), comments: {}, note: f.note.value.trim(), declined: true };
    } else {
      const r = f.collect(true, fields);
      if (r.problems.length) {
        f.form.querySelector(".invalid")?.scrollIntoView({ behavior: smooth(), block: "start" });
        f.form.querySelector<HTMLElement>(".invalid [aria-describedby]")?.focus({ preventScroll: true });
        return;
      }
      if (all && unseen) { // don't send questions the user hasn't seen as "skipped"
        f.err.textContent = "New questions just arrived. Have a look, then send again.";
        first?.scrollIntoView({ behavior: smooth(), block: "start" });
        unseen = 0;
        return;
      }
      a = all ? r.a : { ...r.a, note: "" };
    }
    busy(true);
    try {
      const seqs = ps.map((p) => p.seq);
      await send(sid, keys, st, seqs, { seqs, ...a });
      if (all) {
        seen.disconnect();
        show(sentState());
      } else {
        for (const p of ps) {
          p.foot.replaceWith(h("p", { className: "batch-sent" }, icon("check"), `Sent ${p.fields.length === 1 ? "1 answer" : `${p.fields.length} answers`}`));
          f.remove(p.fields);
          parts.splice(parts.indexOf(p), 1);
        }
        f.form.classList.toggle("multi", parts.length > 1);
        f.err.textContent = "";
        busy(false);
      }
    } catch (x) {
      busy(false);
      const m = (x as Error).message;
      f.err.textContent = m === "Failed to fetch" ? "Couldn't reach the relay. Check your connection and send again." : `Not sent: ${m}. Try again.`;
    }
    done();
  };

  const o: Open = {
    f, sending: false,
    add([s, b]) {
      const r = f.append(b);
      part(s, r.fields);
      if (Date.now() - born < 1000) return; // replayed after a reload, not new
      const el = r.els[0];
      unseen += b.questions.length;
      first ??= el;
      const above = el.getBoundingClientRect().bottom < 0;
      const text = `${unseen} new question${unseen === 1 ? "" : "s"} ${above ? "above" : "below"}`;
      chip.replaceChildren(icon(above ? "up" : "down"), text);
      said.textContent = text;
      if (!chip.isConnected) f.form.append(chip);
      seen.observe(el);
      if (document.hidden) document.title = "● asku: new questions";
    },
  };
  part(seq, f.fields.slice());
  rest.forEach(o.add);
  f.form.onsubmit = (e) => { e.preventDefault(); submit(parts); };
  show(f.form);
  scrollTo(0, 0);
  if (document.hidden) document.title = "● asku: question waiting";
  return o;
}

document.addEventListener("visibilitychange", () => { if (!document.hidden && document.title.startsWith("●")) document.title = "asku"; });

// Text with a copy button. It wraps, so a long link stays readable on a phone.
function copyable(text: string, prompt?: string, label = "Copy") {
  const field = h("code", { className: "copy-text", textContent: text });
  const lbl = h("span", { textContent: "Copy" });
  const copy = h("button", { type: "button", className: "copy-btn", ...(label !== "Copy" && { ariaLabel: `Copy ${label.toLowerCase()}` }) }, icon("copy"), lbl);
  copy.onclick = () => navigator.clipboard.writeText(text).then(() => {
    lbl.textContent = "Copied";
    copy.classList.add("ok");
    setTimeout(() => { lbl.textContent = "Copy"; copy.classList.remove("ok"); }, 2000);
  }, () => getSelection()?.selectAllChildren(field));
  return h("div", { className: "copy" }, prompt ? h("span", { className: "copy-prompt", textContent: prompt, ariaHidden: "true" }) : null, field, copy);
}

